import React, { useEffect, useState, useRef } from 'react';
import { cn } from "@/lib/utils";
import { usePrefersReducedMotion } from "./use-animation-hooks";

interface DecryptedTextProps {
  text: string;
  className?: string;
  speed?: number;
  maxIterations?: number;
  sequential?: boolean;
  useHover?: boolean;
  characters?: string;
}

const DEFAULT_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:"",./<>?';

export const DecryptedText: React.FC<DecryptedTextProps> = ({
  text,
  className,
  speed = 50,
  maxIterations = 10,
  sequential = true,
  useHover = true,
  characters = DEFAULT_CHARS,
}) => {
  const [displayText, setDisplayText] = useState(text);
  const [isDecrypting, setIsDecrypting] = useState(false);
  const triggerRef = useRef<HTMLSpanElement>(null);
  const timerRef = useRef<number | null>(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  const startDecryption = () => {
    if (isDecrypting || prefersReducedMotion) return;
    setIsDecrypting(true);

    let iteration = 0;
    const length = text.length;

    // Clear previous timer
    if (timerRef.current) {
      clearInterval(timerRef.current);
    }

    timerRef.current = window.setInterval(() => {
      setDisplayText(() => {
        return text
          .split('')
          .map((char, index) => {
            if (char === ' ') return ' ';

            if (sequential) {
              // Sequentially decrypt characters from left to right
              const revealThreshold = Math.floor(iteration / maxIterations);
              if (index < revealThreshold) {
                return text[index];
              }
            } else {
              // Randomized decryption
              if (Math.random() < iteration / (maxIterations * length)) {
                return text[index];
              }
            }

            // Return a random scramble character
            const randomIndex = Math.floor(Math.random() * characters.length);
            return characters[randomIndex];
          })
          .join('');
      });

      iteration++;

      const isFinished = sequential
        ? Math.floor(iteration / maxIterations) >= length
        : displayText === text && iteration > maxIterations;

      if (isFinished) {
        setDisplayText(text);
        setIsDecrypting(false);
        if (timerRef.current) {
          clearInterval(timerRef.current);
        }
      }
    }, speed);
  };

  useEffect(() => {
    if (prefersReducedMotion) return;
    // Start automatically on mount
    startDecryption();

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: re-run decryption only when text/motion preference changes
  }, [text, prefersReducedMotion]);

  const handleMouseEnter = () => {
    if (useHover && !prefersReducedMotion) {
      startDecryption();
    }
  };

  return (
    <span
      ref={triggerRef}
      onMouseEnter={handleMouseEnter}
      className={cn(
        'font-mono select-none transition-colors duration-200 cursor-default text-foreground',
        isDecrypting && 'text-primary',
        className
      )}
      style={isDecrypting ? { filter: 'drop-shadow(0 0 8px rgba(var(--primary-rgb), 0.5))' } : undefined}
    >
      {displayText}
    </span>
  );
};

import { useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';

export const usePrefersReducedMotion = (): boolean => {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const listener = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', listener);
    return () => {
      mediaQuery.removeEventListener('change', listener);
    };
  }, []);

  return prefersReducedMotion;
};

export const useAnimateOnScroll = (options?: IntersectionObserverInit) => {
  const [ref, setRef] = useState<HTMLElement | null>(null);
  const [isIntersecting, setIsIntersecting] = useState(false);

  useEffect(() => {
    if (!ref) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry) {
        setIsIntersecting(entry.isIntersecting);
      }
    }, options);

    observer.observe(ref);
    return () => {
      observer.unobserve(ref);
    };
  }, [ref, options]);

  return [setRef, isIntersecting] as const;
};

export function useInView<T extends Element = HTMLDivElement>(
  options: IntersectionObserverInit = { rootMargin: '100px 0px', threshold: 0 },
): [RefObject<T | null>, boolean] {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === 'undefined' || !('IntersectionObserver' in window)) {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), options);
    io.observe(el);
    return () => io.disconnect();
  }, [options]);
  return [ref, inView];
}

export function useShouldAnimate<T extends Element = HTMLDivElement>(): [RefObject<T | null>, boolean] {
  const reduced = usePrefersReducedMotion();
  const [ref, inView] = useInView<T>();
  return [ref, inView && !reduced];
}
